package com.gymflow.app;
import android.app.AlertDialog; import android.os.Bundle; import android.widget.*; import androidx.appcompat.app.AppCompatActivity; import org.json.*;
public class TeachersActivity extends AppCompatActivity {
 private LinearLayout list;
 @Override protected void onCreate(Bundle b){super.onCreate(b);ScrollView s=new ScrollView(this);LinearLayout r=Ui.page(this);s.addView(r);Ui.backHeader(this,r,"Profesores");r.addView(Ui.subtitle(this,"Profesores del gimnasio. En una próxima etapa podrán tener su propio acceso."));Button add=Ui.button(this,"+ Agregar profesor");add.setOnClickListener(v->dialog());r.addView(add);list=new LinearLayout(this);list.setOrientation(LinearLayout.VERTICAL);r.addView(list);load();setContentView(s);}
 private void load(){list.removeAllViews();Cloud.get(this,"gf_teachers","select=id,full_name,specialty,active&owner_id=eq."+Session.uid(this)+"&order=full_name.asc",(c,b)->{try{JSONArray a=new JSONArray(b);if(a.length()==0)list.addView(Ui.card(this,"Sin profesores","Podés administrar el gimnasio solo o agregar profesores."));for(int i=0;i<a.length();i++){JSONObject o=a.getJSONObject(i);String id=o.optString("id"),name=o.optString("full_name");TextView t=Ui.card(this,name,o.optString("specialty","Profesor")+(o.optBoolean("active")?" · Activo":" · Inactivo"));t.setOnClickListener(v->new AlertDialog.Builder(this).setTitle(name).setItems(new String[]{"Activar / desactivar","Eliminar"},(d,w)->{if(w==0)try{JSONObject x=new JSONObject();x.put("active",!o.optBoolean("active"));Cloud.patch(this,"gf_teachers","id=eq."+id,x,(cc,bb)->load());}catch(Exception ignored){}else Cloud.delete(this,"gf_teachers","id=eq."+id,(cc,bb)->load());}).show());list.addView(t);}}catch(Exception e){list.addView(Ui.card(this,"Error",Cloud.err(b)));}});}
 private void dialog(){LinearLayout box=Ui.page(this);EditText name=Ui.input(this,"Nombre y apellido");box.addView(name);EditText spec=Ui.input(this,"Especialidad");box.addView(spec);new AlertDialog.Builder(this).setTitle("Nuevo profesor").setView(box).setNegativeButton("Cancelar",null).setPositiveButton("Guardar",(d,w)->{try{if(name.getText().toString().trim().isEmpty())return;JSONObject o=new JSONObject();o.put("owner_id",Session.uid(this));o.put("full_name",name.getText().toString().trim());o.put("specialty",spec.getText().toString().trim());Cloud.post(this,"gf_teachers",o,(c,b)->{if(c>=200&&c<300)load();else Toast.makeText(this,Cloud.err(b),Toast.LENGTH_LONG).show();});}catch(Exception ignored){}}).show();}
}
